from hypothesis import given, strategies as st
from enoch_control_plane.control_plane.paper_writer import _flatten_json_metrics

scalar = st.none() | st.booleans() | st.integers() | st.floats(allow_nan=False, allow_infinity=False) | st.text(max_size=20)
jsonish = st.recursive(scalar, lambda c: st.lists(c, max_size=8) | st.dictionaries(st.text(max_size=12), c, max_size=8), max_leaves=40)
@given(jsonish, st.integers(min_value=1, max_value=25))
def test_flatten_json_metrics_respects_limit_and_leaf_shapes(value, limit):
    result = _flatten_json_metrics(value, limit=limit)
    assert isinstance(result, dict)
    assert len(result) <= limit
    for key, val in result.items():
        assert isinstance(key, str) and key
        if isinstance(val, list):
            assert len(val) <= 20
            assert all(x is None or isinstance(x, (int, float, str, bool)) for x in val)
        else:
            assert val is None or isinstance(val, (int, float, str, bool))
